#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdint>

using namespace std;

const double PI = acos(-1.0);

// Helper: highest power of two <= x (x > 0)
int highestOneBit(int x) {
    int res = 1;
    while (res <= x) res <<= 1;
    return res >> 1;
}

// Helper: number of trailing zeros (n > 0)
int trailingZeros(int n) {
    int cnt = 0;
    while ((n & 1) == 0) {
        n >>= 1;
        cnt++;
    }
    return cnt;
}

// Helper: reverse bits of a 32-bit integer
unsigned int reverseBits(unsigned int x) {
    unsigned int rev = 0;
    for (int i = 0; i < 32; i++) {
        rev = (rev << 1) | (x & 1);
        x >>= 1;
    }
    return rev;
}

// FFT on two real arrays (real and imaginary parts)
void fft(vector<double>& a, vector<double>& b, bool inverse) {
    int n = a.size();
    int shift = 32 - trailingZeros(n);
    for (int i = 1; i < n; i++) {
        int j = reverseBits(i << shift);
        if (i < j) {
            swap(a[i], a[j]);
            swap(b[i], b[j]);
        }
    }
    for (int len = 2; len <= n; len <<= 1) {
        int halfLen = len >> 1;
        vector<double> cs(halfLen), sn(halfLen);
        double angle = 2.0 * PI / len * (inverse ? -1 : 1);
        for (int i = 0; i < halfLen; i++) {
            cs[i] = cos(angle * i);
            sn[i] = sin(angle * i);
        }
        for (int i = 0; i < n; i += len) {
            for (int j = 0; j < halfLen; j++) {
                double wA = cs[j];
                double wB = sn[j];
                double uA = a[i + j];
                double uB = b[i + j];
                double vA = a[i + j + halfLen] * wA - b[i + j + halfLen] * wB;
                double vB = a[i + j + halfLen] * wB + b[i + j + halfLen] * wA;
                a[i + j] = uA + vA;
                b[i + j] = uB + vB;
                a[i + j + halfLen] = uA - vA;
                b[i + j + halfLen] = uB - vB;
            }
        }
    }
    if (inverse) {
        for (int i = 0; i < n; i++) {
            a[i] /= n;
            b[i] /= n;
        }
    }
}

// Polynomial multiplication modulo mod using FFT
vector<int> multiplyMod(const vector<int>& a, const vector<int>& b, int mod) {
    int need = a.size() + b.size() - 1;
    int n = 1;
    while (n < need) n <<= 1;
    if (n < 2) n = 2;

    vector<double> aReal(n, 0.0), aImag(n, 0.0);
    for (int i = 0; i < (int)a.size(); i++) {
        int x = (a[i] % mod + mod) % mod;
        aReal[i] = x & ((1 << 15) - 1);
        aImag[i] = x >> 15;
    }
    fft(aReal, aImag, false);

    vector<double> bReal(n, 0.0), bImag(n, 0.0);
    for (int i = 0; i < (int)b.size(); i++) {
        int x = (b[i] % mod + mod) % mod;
        bReal[i] = x & ((1 << 15) - 1);
        bImag[i] = x >> 15;
    }
    fft(bReal, bImag, false);

    vector<double> faReal(n), faImag(n), fbReal(n), fbImag(n);
    double cf = 0.25 / n; // not used, but kept for consistency
    for (int i = 0; i < n; i++) {
        int j = (n - i) & (n - 1);

        double a1r = (aReal[i] + aReal[j]) / 2;
        double a1i = (aImaginary[i] - aImaginary[j]) / 2;
        double a2r = (aImaginary[i] + aImaginary[j]) / 2;
        double a2i = (aReal[j] - aReal[i]) / 2;

        double b1r = (bReal[i] + bReal[j]) / 2;
        double b1i = (bImaginary[i] - bImaginary[j]) / 2;
        double b2r = (bImaginary[i] + bImaginary[j]) / 2;
        double b2i = (bReal[j] - bReal[i]) / 2;

        faReal[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
        faImaginary[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;

        fbReal[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
        fbImaginary[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
    }

    fft(faReal, faImaginary, true);
    fft(fbReal, fbImaginary, true);

    vector<int> res(need);
    for (int i = 0; i < need; i++) {
        long long aa = (long long)(faReal[i] + 0.5);
        long long bb = (long long)(fbReal[i] + 0.5);
        long long cc = (long long)(faImaginary[i] + 0.5);
        res[i] = (int)((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
    }
    return res;
}

int main() {
    const int MOD = 998244353;
    int n, k;
    cin >> n >> k;
    vector<int> v(10, 0);
    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        v[x] = 1;
    }

    vector<int> ans = {1};
    int p = n / 2;
